        {"원어":"προφήταις (프로페타이스)", "의미_문법":"선지자들로 - 복수 여격. 구약의 선지자들이 복음의 증인임을 확증", "설교포인트":"구약의 선지자들은 모두 그리스도를 향해 있다"}
