        {"구절":"암 3:2", "연결점":"땅의 모든 족속 중에 내가 너희만 알았나니 그러므로 내가 너희 모든 죄악을 너희에게 보응하리라", "구분":"구약"},
        {"구절":"겔 5:5-6", "연결점":"주 여호와가 이같이 말씀하시되 이것이 예루살렘이라 내가 그를 이방인 가운데 두고 각 나라가 에워싸게 하였거늘 이 예루살렘이 나의 규례를 거슬러 악을 행하되", "구분":"구약"},
        {"구절":"암 1:3-2:3", "연결점":"아모스 1-2장에서 이방 민족들이 일반 도덕 기준으로 심판받는 사례들", "구분":"구약"},
        {"구절":"눅 12:47-48", "연결점":"주인의 뜻을 알고도 예비치 아니한 종은 많이 맞겠고 알지 못하고 맞을 일을 한 종은 적게 맞으리라", "구분":"신약"},
        {"구절":"요 15:22", "연결점":"내가 와서 말하지 아니하였더라면 죄가 없었으려니와 지금은 그 죄를 핑계할 수 없느니라", "구분":"신약"},
        {"구절":"행 17:30", "연결점":"알지 못하던 시대에는 하나님이 허물치 아니하셨거니와 이제는 어디든지 사람을 다 명하사 회개하라 하셨으니", "구분":"신약"},
        {"구절":"약 4:17", "연결점":"이러므로 사람이 선을 행할 줄 알고도 행치 아니하면 죄니라", "구분":"신약"}
