    표1_원어분석: [
        {"원어":"ὁδηγὸν τυφλῶν (호데곤 튀플론)", "의미_문법":"소경의 길잡이 - '눈먼 자들의 안내자'. 유대인이 이방인에 대해 가졌던 자부심 — 하나님의 진리를 가르치는 사명자", "설교포인트":"가르치는 자의 삶이 가르침과 일치해야 한다"},
        {"원어":"φῶς τῶν ἐν σκότει (포스 톤 엔 스코테이)", "의미_문법":"어두움에 있는 자의 빛 - '어둠 속에 있는 자들의 빛'. 이방인을 영적 어둠 속에 있는 자들로 보는 유대인의 관점", "설교포인트":"빛 되신 자가 빛 답게 살아야 한다"}
    ],
    표2_역사적배경: [
        {"항목":"이사야의 이스라엘 사명", "내용":"사 42:6-7에서 이스라엘은 '열방의 빛, 눈먼 자의 눈을 밝히는' 사명을 받았다. 유대인들은 이 사명 의식을 강하게 가졌다. 바울은 이 사명이 실제로 실현되고 있는지 질문한다.", "목회적활용":"교회의 사명(빛과 소금)이 실제 삶에서 실현되어야 함을 가르친다"},
        {"항목":"유대인 선교사들의 자부심", "내용":"1세기에 유대인들은 이방인들에게 유일신 신앙과 도덕 윤리를 가르쳤다. 일부 이방인들이 유대교로 개종했다(하나님을 경외하는 자들). 이것이 유대인의 자부심이었다.", "목회적활용":"선교적 열심이 자기 삶의 일관성을 요구함을 가르친다"},
        {"항목":"예수님의 제자들을 '빛'이라 부르심", "내용":"예수님이 제자들을 '세상의 빛'(마 5:14)이라 부르신 것은 이스라엘의 사명을 교회가 이어받음을 의미한다. 그러나 이 빛은 삶으로 비추어야 한다(마 5:16).", "목회적활용":"교회의 빛 됨이 말이 아닌 삶으로 빛나야 함을 가르친다"}
    ],
    표3_신학적의미: [
        {"교리":"선교적 소명과 삶의 일치", "설명":"소경의 길잡이, 어둠 속의 빛이라는 사명은 아름다운 소명이다. 그러나 길잡이의 삶과 안내가 일치해야 한다. 그렇지 않으면 소경이 소경을 인도하는 격이 된다.", "관련구절":"사 42:6-7, 마 5:14-16, 롬 2:21"},
        {"교리":"이스라엘의 사명과 교회의 사명", "설명":"이스라엘에게 주어진 열방의 빛이 되는 사명은 그리스도 안에서 교회로 이어진다. 교회는 세상의 빛이 되어야 한다.", "관련구절":"사 49:6, 마 5:14, 행 13:47"},
        {"교리":"삶의 일관성(integrity)의 신학", "설명":"공적으로 주장하는 것과 사적으로 사는 것이 일치해야 한다. 이것이 삶의 일관성(integrity)이다. 위선(hypocrisy)은 두 얼굴이다.", "관련구절":"마 23:3, 딤전 4:12, 딛 2:7-8"}
    ],
    표4_예표론: [
        {"구분":"이사야의 종의 노래", "내용":"사 42:6-7의 '소경의 눈을 밝히며 어둠에 앉은 자들을 밝힌다'는 이스라엘의 사명이 바울 논증의 배경이다", "그리스도연결":"그리스도는 이 사명의 완전한 성취이시다 (눅 4:18-19, 요 9:5)"},
        {"구분":"등불 아래 숨기는 자 비판", "내용":"예수님이 등불을 그릇 아래 두지 말고 등경 위에 두라(마 5:15)고 하신 것은 빛의 사명이 공개적으로 삶에서 빛나야 함을 가르친다", "그리스도연결":"그리스도는 세상의 빛이시며(요 8:12), 우리가 그분 안에서 빛이 된다 (엡 5:8)"},
        {"구분":"모세의 빛남", "내용":"시내산에서 하나님과 교통한 후 모세의 얼굴이 빛난 것(출 34:29-30)은 하나님과의 실제 교통이 삶을 빛나게 함을 보여준다", "그리스도연결":"그리스도는 하나님의 영광의 빛이시며(히 1:3), 그분을 바라볼 때 우리도 변화된다 (고후 3:18)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"A guide of the blind — a great honour if true; but the worst of all censures if those who assume it are themselves blind.", "한국어번역":"소경의 길잡이 — 사실이라면 큰 영예이다. 그러나 이것을 자처하는 자들이 자신이 소경이라면 모든 책망 중 가장 나쁜 것이다.", "핵심통찰":"가르치는 자가 먼저 보아야 한다"},
        {"영어원문":"A light to them which are in darkness — light is the most valuable thing; to be a light-giver is a most honourable function, but requires the light to be genuine.", "한국어번역":"어둠 속에 있는 자들에게 빛 — 빛은 가장 귀한 것이다. 빛을 주는 자가 되는 것은 가장 영예로운 기능이지만 그 빛이 진짜여야 한다.", "핵심통찰":"진짜 빛이어야 다른 사람에게 빛이 될 수 있다"},
        {"영어원문":"These are dignities that carry with them obligations; to be the guide of the blind demands that your own sight be clear.", "한국어번역":"이것들은 의무를 수반하는 품위이다. 소경의 길잡이가 되는 것은 당신 자신의 시력이 명확해야 한다는 것을 요구한다.", "핵심통찰":"사명과 자격은 함께 간다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"소경의 길잡이, 어둠의 빛 — 사명과 삶의 일치를 요구하다", "예화_적용":"사명을 주장하지만 삶이 따르지 않는 위험을 경고한다"},
        {"대지":"서론", "내용":"길을 모르는 사람이 길잡이 역할을 하려 한다. 이보다 위험한 것이 있는가? 바울은 이방인의 길잡이를 자처하는 유대인에게 묻는다 — 당신 자신은 그 길을 가고 있는가?", "예화_적용":"GPS를 믿고 따라갔더니 낭떠러지로 안내된 사례 — 잘못된 길잡이의 위험성"},
        {"대지":"1대지: 소경의 길잡이 (사명과 자격)", "내용":"길잡이는 자신이 먼저 길을 알고 가야 한다. 소경이 소경을 인도하면 둘 다 구덩이에 빠진다(마 15:14).", "예화_적용":"안전 교육 강사가 안전 규칙을 무시한다면 교육이 의미 없다 — 가르치는 자의 일관성"},
        {"대지":"2대지: 어둠의 빛 (삶의 일관성)", "내용":"빛이 되려면 자신이 먼저 빛이어야 한다. 빛이라고 주장하면서 어둠 속에 사는 것은 가장 어두운 위선이다.", "예화_적용":"마 5:16 '이같이 너희 빛을 사람 앞에 비취게 하여 그들로 너희 착한 행실을 보고 하늘에 계신 너희 아버지께 영광을 돌리게 하라'"},
        {"대지":"3대지: 사명의 아름다움 (제대로 된 빛)", "내용":"소경의 길잡이, 어둠의 빛이 되는 것은 정말 아름다운 사명이다. 이 사명을 삶으로 실현할 때 진정한 영향력이 생긴다.", "예화_적용":"진짜 빛이 된 사람들 — 윌리엄 윌버포스, 마더 테레사 등 삶으로 빛이 된 역사적 인물들"},
        {"대지":"결론", "내용":"우리에게도 소경의 길잡이, 어둠의 빛이 되라는 사명이 있다. 이 사명을 먼저 자신의 삶에서 실현하라. 삶으로 빛날 때 사명이 의미를 갖는다.", "예화_적용":"마 5:14-16 세상의 빛으로 부름받은 우리의 사명과 책임"}
    ],
