        {"새찬송가":"213", "통일찬송가":"254", "제목":"주 예수 내 맘에 들어와 계신 후", "선정이유":"내면의 변화 없이 외적 종교행위만 반복하는 위선에서 벗어나는 은혜를 노래"},
        {"새찬송가":"384", "통일찬송가":"434", "제목":"나 어느 곳에 있든지", "선정이유":"어디서나 주님 앞에 일관된 삶을 살겠다는 결단에 적합"},
        {"새찬송가":"272", "통일찬송가":"337", "제목":"내 죄 사함 받고서", "선정이유":"위선을 회개하고 은혜로 새출발하는 결단에 적합"}
